"""Strict Output Schema Validation for Neural Proposals."""
from __future__ import annotations

import json
import re
from typing import Any, Dict, Optional, Tuple


class OutputValidationError(Exception):
    """Raised when output generated by a neural model fails schema or boundary validation."""
    pass


class ProposalOutputValidator:
    """Validates raw model output against typed UoW grammar schemas."""

    @staticmethod
    def extract_json(raw_text: str) -> Optional[dict[str, Any]]:
        """Robustly extracts JSON substring from model output."""
        cleaned = raw_text.strip()
        # Direct parse attempt
        try:
            return json.loads(cleaned)
        except Exception:
            pass

        # Match markdown fenced code blocks
        match = re.search(r"```(?:json)?\s*([\s\S]*?)\s*```", cleaned)
        if match:
            try:
                return json.loads(match.group(1))
            except Exception:
                pass

        # Match innermost balanced braces
        first_brace = cleaned.find("{")
        last_brace = cleaned.rfind("}")
        if first_brace != -1 and last_brace > first_brace:
            candidate = cleaned[first_brace : last_brace + 1]
            try:
                return json.loads(candidate)
            except Exception:
                pass

        return None

    @classmethod
    def validate_proposal(
        cls,
        raw_text: str,
        expected_grammar: str,
    ) -> tuple[bool, Optional[dict[str, Any]], Optional[str]]:
        """Validates output against expected grammar schema.
        
        Returns (is_valid, parsed_dict, error_reason).
        """
        parsed = cls.extract_json(raw_text)
        if parsed is None:
            return False, None, "Invalid JSON formatting"

        if expected_grammar == "operational":
            required_keys = {"domain", "action", "disposition", "parameters", "guard_conditions", "unknowns"}
            missing = required_keys - set(parsed.keys())
            if missing:
                return False, parsed, f"Missing operational schema keys: {sorted(missing)}"
            if parsed.get("disposition") not in ("COMMIT", "ROLLBACK", "HALT"):
                return False, parsed, f"Invalid disposition value: '{parsed.get('disposition')}'"

        elif expected_grammar == "temporal":
            core_keys = {"domain", "target_action", "relation"}
            missing = core_keys - set(parsed.keys())
            if missing:
                return False, parsed, f"Missing temporal schema keys: {sorted(missing)}"
            valid_relations = {"BEFORE", "AFTER", "CONCURRENT", "WITHIN", "IMMEDIATE", "BETWEEN"}
            if parsed.get("relation") not in valid_relations:
                return False, parsed, f"Invalid temporal relation: '{parsed.get('relation')}'"

        elif expected_grammar == "recovery":
            core_keys = {"domain", "strategy"}
            missing = core_keys - set(parsed.keys())
            if missing:
                return False, parsed, f"Missing recovery schema keys: {sorted(missing)}"
            if not any(k in parsed for k in ("failure_mode", "failed_action", "failure_class")):
                return False, parsed, "Missing failure identifier key ('failure_mode', 'failed_action', or 'failure_class')"
            valid_strategies = {
                "RETRY", "ROLLBACK_COMPENSATE", "FAILOVER", "ESCALATE_HUMAN",
                "IMMEDIATE_RETRY", "CIRCUIT_BREAK", "EXPONENTIAL_BACKOFF", "ESCALATE_OPERATOR"
            }
            if parsed.get("strategy") not in valid_strategies:
                return False, parsed, f"Invalid recovery strategy: '{parsed.get('strategy')}'"

        return True, parsed, None
